namespace ghidra.framework.main.datatree;



using docking.widgets.table;
using docking.widgets.table;
using ghidra.framework.store;

/**
 * Table model for showing version history.
 */
class VersionHistoryTableModel : AbstractSortedTableModel<Version> {

	static string DATE = "Version Date";
	static string VERSION = "Version";
	static string USER = "User";
	static string COMMENTS = "Comments";

	// columns used in the getValueAt() method
	static int VERSION_COL = 0;
	static int DATE_COL = 1;
	static int USER_COL = 2;
	static int COMMENTS_COL = 3;

	private string[] columnNames = new string[] { VERSION, DATE, USER, COMMENTS };

	private List<Version> versionList;

	VersionHistoryTableModel(Version[] versions) {
		versionList = new();
		foreach (Version version in versions) {
			versionList.add(version);
		}
		setDefaultTableSortState(TableSortState.createDefaultSortState(VERSION_COL, false));
	}

	/* @Override */
	public string getName() {
		return "Version History";
	}

	/* @Override */
	public int getColumnCount() {
		return columnNames.length;
	}

	/* @Override */
	public Class<object> getColumnClass(int columnIndex) {
		if (columnIndex == DATE_COL) {
			return typeof(Date);
		}
		if (columnIndex == VERSION_COL) {
			return typeof(Integer);
		}
		return typeof(string);
	}

	/* @Override */
	public string getColumnName(int column) {
		return columnNames[column];
	}

	void refresh(Version[] newVersions) {
		List<Version> newVersionList = new();
		foreach (Version version in newVersions) {
			newVersionList.add(version);
		}
		versionList = newVersionList;
		fireTableDataChanged();
	}

	Version getVersionAt(int row) {
		if (row < 0 || row >= versionList.size()) {
			return null;
		}
		return versionList.get(row);
	}

	/* @Override */
	public object getColumnValueForRow(Version version, int columnIndex) {
		switch (columnIndex) {
			case VERSION_COL:
				return version.getVersion();
			case DATE_COL:
				return new Date(version.getCreateTime());
			case USER_COL:
				return version.getUser();
			case COMMENTS_COL:
				return version.getComment();
		}
		return null;
	}

	/* @Override */
	public List<Version> getModelData() {
		return versionList;
	}

	/* @Override */
	public bool isSortable(int columnIndex) {
		return true;
	}

}
